      +(window.curLang==='lanqiao'?'':'<select id="exTagSel" onchange="filterExList()" style="padding:8px 10px;border:1px solid #e0e0e0;border-radius:8px;font-size:13px;background:#fafafa;outline:none;flex-shrink:0">')
