      +"<div style=\"background:white;border-radius:16px;padding:28px;max-width:680px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,.25);max-height:90vh;overflow-y:auto;animation:slideUp 0.3s ease\">"
